    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    # Locate each rectangular outline independently, including multiple outlines
    # of the same color.
    for color in set(v for row in g for v in row):
        if color == bg:
            continue
        for r1 in range(h - 2):
            for r2 in range(r1 + 2, h):
                for c1 in range(w - 2):
                    for c2 in range(c1 + 2, w):
                        if (all(g[r1][c] == color for c in range(c1, c2 + 1)) and
                            all(g[r2][c] == color for c in range(c1, c2 + 1)) and
                            all(g[r][c1] == color for r in range(r1, r2 + 1)) and
                            all(g[r][c2] == color for r in range(r1, r2 + 1))):
                            inner_h, inner_w = r2 - r1 - 1, c2 - c1 - 1
                            fill = 2 if inner_h % 2 == 0 else 7
                            for r in range(r1 + 1, r2):
                                for c in range(c1 + 1, c2):
                                    g[r][c] = fill
    return g
